import { z } from 'zod';

const NONE_HEAD = '0';

export const AddDepartmentSchema = z.object({
    name: z.string().min(1, 'اسم القسم مطلوب').max(255, 'الاسم طويل جداً'),
    description: z.string().optional().nullable(),
    /** Employee id as string; "0" = no admin */
    department_head_id: z.string().optional(),
    max_employees: z.coerce.number().int().min(1, 'الحد الأقصى للموظفين مطلوب (رقم صحيح ≥ 1)'),
});

export type AddDepartmentFormValues = z.infer<typeof AddDepartmentSchema>;

export function headIdForApi(value: string | undefined): number | null {
    const v = value?.trim();
    if (!v || v === NONE_HEAD) return null;
    const n = Number(v);
    return Number.isFinite(n) && n > 0 ? n : null;
}
